/**
 * HTTP entry: assigns a request id to every incoming request, refuses it when
 * the client has spent its rate-limit window, and otherwise hands it to the
 * router. This is where the request id is born.
 */
import { randomUUID } from "node:crypto";
import { Router, type RouteRequest, type RouteResponse } from "./router.ts";
import { RateLimiter, type RateLimiterOptions } from "./RateLimiter.ts";
import { JobQueue } from "../jobs/JobQueue.ts";
import { AppLogger, type Sink } from "../platform/logging/AppLogger.ts";

export interface IncomingRequest {
  readonly method: RouteRequest["method"];
  readonly path: string;
  readonly headers: Record<string, string | undefined>;
  readonly body?: unknown;
}

export interface AppOptions {
  readonly rateLimit?: RateLimiterOptions;
}

/** Headers arrive unnormalised, so a header is matched on its lowercased name. */
function header(headers: IncomingRequest["headers"], name: string): string | undefined {
